1	import Templates from "@/components/dropdowns/templates";
2	import makeKeyboardNavigable from "@/util/keyboard";
3	import tippy from "tippy.js";
4	import behaviorShim from "@/util/behavior-shim";
5	
6	const SELECTED_ITEM_CLASS = "jenkins-dropdown__item--selected";
7	
8	/*
9	 * Generates the dropdowns for the given element
10	 * Preloads the data on hover for speed
11	 * @param element - the element to generate the dropdown for
12	 * @param callback - called to retrieve the list of dropdown items
13	 */
14	function generateDropdown(element, callback) {
15	  tippy(
16	    element,
17	    Object.assign({}, Templates.dropdown(), {
18	      onCreate(instance) {
19	        instance.reference.addEventListener("mouseenter", () => {
20	          if (instance.loaded) {
21	            return;
22	          }
23	
24	          instance.popper.addEventListener("click", () => {
25	            instance.hide();
26	          });
27	
28	          callback(instance);
29	        });
30	      },
31	    }),
32	  );
33	}
34	
35	/*
36	 * Generates the contents for the dropdown
37	 */
38	function generateDropdownItems(items, compact) {
39	  const menuItems = document.createElement("div");
40	  menuItems.classList.add("jenkins-dropdown");
41	  if (compact === true) {
42	    menuItems.classList.add("jenkins-dropdown--compact");
43	  }
44	
45	  items
46	    .map((item) => {
47	      if (item.type === "CUSTOM") {
48	        return item.contents;
49	      }
50	
51	      if (item.type === "HEADER") {
52	        return Templates.heading(item.label);
53	      }
54	
55	      if (item.type === "SEPARATOR") {
56	        return Templates.separator();
57	      }
58	
59	      if (item.type === "DISABLED") {
60	        return Templates.disabled(item.label);
61	      }
62	
63	      const menuItem = Templates.menuItem(item);
64	
65	      if (item.subMenu != null) {
66	        tippy(
67	          menuItem,
68	          Object.assign({}, Templates.dropdown(), {
69	            content: generateDropdownItems(item.subMenu()),
70	            trigger: "mouseenter",
71	            placement: "right-start",
72	            offset: [-8, 0],
73	          }),
74	        );
75	      }
76	
77	      return menuItem;
78	    })
79	    .forEach((item) => menuItems.appendChild(item));
80	
81	  if (items.length === 0) {
82	    menuItems.appendChild(Templates.placeholder("No items"));
83	  }
84	
85	  makeKeyboardNavigable(
86	    menuItems,
87	    () => menuItems.querySelectorAll(".jenkins-dropdown__item"),
88	    SELECTED_ITEM_CLASS,
89	    (selectedItem, key) => {
90	      switch (key) {
91	        case "ArrowLeft": {
92	          const root = selectedItem.closest("[data-tippy-root]");
93	          if (root) {
94	            const tippyReference = root._tippy;
95	            if (tippyReference) {
96	              tippyReference.hide();
97	            }
98	          }
99	          break;
100	        }
101	        case "ArrowRight": {
102	          const tippyRef = selectedItem._tippy;
103	          if (!tippyRef) {
104	            break;
105	          }
106	
107	          tippyRef.show();
108	          tippyRef.props.content
109	            .querySelector(".jenkins-dropdown__item")
110	            .classList.add(SELECTED_ITEM_CLASS);
111	          break;
112	        }
113	      }
114	    },
115	    (container) => {
116	      const isVisible =
117	        window.getComputedStyle(container).visibility === "visible";
118	      const isLastDropdown = Array.from(
119	        document.querySelectorAll(".jenkins-dropdown"),
120	      )
121	        .filter((dropdown) => container !== dropdown)
122	        .filter(
123	          (dropdown) =>
124	            window.getComputedStyle(dropdown).visibility === "visible",
125	        )
126	        .every(
127	          (dropdown) =>
128	            !(
129	              container.compareDocumentPosition(dropdown) &
130	              Node.DOCUMENT_POSITION_FOLLOWING
131	            ),
132	        );
133	
134	      return isVisible && isLastDropdown;
135	    },
136	  );
137	
138	  behaviorShim.applySubtree(menuItems);
139	
140	  return menuItems;
141	}
