143	function convertHtmlToItems(children) {
144	  const items = [];
145	  Array.from(children).forEach((child) => {
146	    const attributes = child.dataset;
147	    const type = child.dataset.dropdownType;
148	
149	    switch (type) {
150	      case "ITEM": {
151	        const item = {
152	          label: attributes.dropdownText,
153	          id: attributes.dropdownId,
154	          icon: attributes.dropdownIcon,
155	          iconXml: attributes.dropdownIcon,
156	          clazz: attributes.dropdownClazz,
157	        };
158	
159	        if (attributes.dropdownHref) {
160	          item.url = attributes.dropdownHref;
161	          item.type = "link";
162	        } else {
163	          item.type = "button";
164	        }
165	
166	        items.push(item);
167	        break;
168	      }
169	      case "SUBMENU":
170	        items.push({
171	          type: "ITEM",
172	          label: attributes.dropdownText,
173	          icon: attributes.dropdownIcon,
174	          iconXml: attributes.dropdownIcon,
175	          subMenu: () => convertHtmlToItems(child.content.children),
176	        });
177	        break;
178	      case "SEPARATOR":
179	        items.push({ type: type });
180	        break;
181	      case "HEADER":
182	        items.push({ type: type, label: attributes.dropdownText });
183	        break;
184	      case "CUSTOM":
185	        items.push({ type: type, contents: child.content.cloneNode(true) });
186	        break;
187	    }
188	  });
189	  return items;
190	}
191	
192	export default {
193	  convertHtmlToItems,
194	  generateDropdown,
195	  generateDropdownItems,
196	};

1	import { createElementFromHtml } from "@/util/dom";
2	import { xmlEscape } from "@/util/security";
