4	function dropdown() {
5	  return {
6	    content: "<p class='jenkins-spinner'></p>",
7	    interactive: true,
8	    trigger: "click",
9	    allowHTML: true,
10	    placement: "bottom-start",
11	    arrow: false,
12	    theme: "dropdown",
13	    appendTo: document.body,
14	    offset: [0, 0],
15	    animation: "dropdown",
16	    onShow: (instance) => {
17	      const referenceParent = instance.reference.parentNode;
18	
19	      if (referenceParent.classList.contains("model-link")) {
20	        referenceParent.classList.add("model-link--open");
21	      }
22	    },
23	    onHide: (instance) => {
24	      const referenceParent = instance.reference.parentNode;
25	      referenceParent.classList.remove("model-link--open");
26	    },
27	  };
28	}
