30	function menuItem(options) {
31	  const itemOptions = Object.assign(
32	    {
33	      type: "link",
34	    },
35	    options,
36	  );
37	
38	  const label = xmlEscape(itemOptions.label);
39	  let badgeText;
40	  let badgeTooltip;
41	  let badgeSeverity;
42	  if (itemOptions.badge) {
43	    badgeText = xmlEscape(itemOptions.badge.text);
44	    badgeTooltip = xmlEscape(itemOptions.badge.tooltip);
45	    badgeSeverity = xmlEscape(itemOptions.badge.severity);
46	  }
47	  const tag = itemOptions.type === "link" ? "a" : "button";
48	
49	  const item = createElementFromHtml(`
50	      <${tag} class="jenkins-dropdown__item ${itemOptions.clazz ? xmlEscape(itemOptions.clazz) : ""}" ${itemOptions.url ? `href="${xmlEscape(itemOptions.url)}"` : ""} ${itemOptions.id ? `id="${xmlEscape(itemOptions.id)}"` : ""}>
51	          ${
52	            itemOptions.icon
53	              ? `<div class="jenkins-dropdown__item__icon">${
54	                  itemOptions.iconXml
55	                    ? itemOptions.iconXml
56	                    : `<img alt="${label}" src="${itemOptions.icon}" />`
57	                }</div>`
58	              : ``
59	          }
60	          ${label}
61	                    ${
62	                      itemOptions.badge != null
63	                        ? `<span class="jenkins-dropdown__item__badge jenkins-badge alert-${badgeSeverity}" tooltip="${badgeTooltip}">${badgeText}</span>`
64	                        : ``
65	                    }
66	          ${
67	            itemOptions.subMenu != null
68	              ? `<span class="jenkins-dropdown__item__chevron"></span>`
69	              : ``
70	          }
71	      </${tag}>
72	    `);
73	
74	  if (options.onClick) {
75	    item.addEventListener("click", (event) => options.onClick(event));
76	  }
77	
78	  return item;
79	}
